B.ahd=new A.lx("intro_1.jpg",1.05,1.18,B.eu,B.et,B.R_)
B.Uc=new A.a0(B.w,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.ah0=new A.e_("luna",B.Uc,"scared")
B.U5=new A.a0(B.w,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
