B.TU=new A.a0(B.w,["{r}?! Ufa, finalmente! R\xe1pido, antes que os rob\xf4s voltem... eu ouvi eles!","{r}?! Phew, finally! Hurry, before the robots come back... I heard them!","\xbf\xa1{r}!? \xa1Uf, por fin! R\xe1pido, antes de que vuelvan los robots... \xa1los o\xed!"],t.w)
B.TA=new A.a0(B.w,["{r}... senti sua energia. Essa c\xe1psula bloqueia meus poderes. Preciso de voc\xea.","{r}... I felt your energy. This capsule blocks my powers. I need you.","{r}... sent\xed tu energ\xeda. Esta c\xe1psula bloquea mis poderes. Te necesito."],t.w)
B.Tj=new A.a0(B.lC,[B.U6,B.U3,B.TU,B.TA],t.vb)
B.ig=new A.a0(B.lC,[2,3,5,8],t.eL)
B.U1=new A.a0(B.w,["Livre! Valeu, Kael! Agora ningu\xe9m me segura... bora atr\xe1s desses chefes!","Free! Thanks, Kael! Now nobody can stop me... let's go after those bosses!","\xa1Libre! \xa1Gracias, Kael! Ahora nadie me detiene... \xa1vamos por esos jefes!"],t.w)
B.Ty=new A.a0(B.w,["At\xe9 que enfim! Agora sim... BUM! Bora derrubar uns chefes!","Finally! Now we're talking... BOOM! Let's take down some bosses!","\xa1Por fin! Ahora s\xed... \xa1BUM! \xa1Vamos a derribar unos jefes!"],t.w)
B.Tt=new A.a0(B.w,["Eu avisei que ia dar errado, n\xe3o avisei? Valeu, parceiro. Minha mira \xe9 sua!","I told you it would go wrong, didn't I? Thanks, partner. My aim is yours!","Te dije que saldr\xeda mal, \xbfo no? Gracias, compa\xf1ero. \xa1Mi punter\xeda es tuya!"],t.w)
B.U0=new A.a0(B.w,["Minha energia voltou... obrigado. Juntos, nada vai nos parar.","My energy is back... thank you. Together, nothing can stop us.","Mi energ\xeda volvi\xf3... gracias. Juntos, nada nos detendr\xe1."],t.w)
B.Tk=new A.a0(B.lC,[B.U1,B.Ty,B.Tt,B.U0],t.vb)
